import { realpathSync, statSync } from 'node:fs';
import { resolve, sep } from 'node:path';

/** Only media generated by this instance can be read by the publisher. */
export function resolveLocalMedia(input: string): string {
  const origin = new URL(process.env.FRONTEND_URL!);
  const url = new URL(input);
  if (url.origin !== origin.origin || url.username || url.password || url.search || url.hash || !url.pathname.startsWith('/uploads/')) {
    throw new Error('Only locally uploaded media is permitted');
  }
  const relative = decodeURIComponent(url.pathname.slice('/uploads/'.length));
  if (!/^\d{4}\/\d{2}\/\d{2}\/[a-f0-9]+\.[a-z0-9]+$/.test(relative)) {
    throw new Error('Invalid local media path');
  }
  const root = realpathSync(process.env.UPLOAD_DIRECTORY!);
  const path = realpathSync(resolve(root, relative));
  if (!path.startsWith(root + sep) || !statSync(path).isFile()) throw new Error('Media path escapes storage');
  return path;
}
